    def fmt(nums, k):
        return f"{len(nums)} {k}\n" + ' '.join(map(str, nums))

    def vals(n):
        return rng.sample(range(-99, 100), n)

    tests = [fmt([5], 1), fmt([3, -4], 2), fmt([3, -4], 1), fmt([0, 1, 2, 3], 4), fmt([9, 8, 7, 6, 5], 1)]
    for n in range(2, 11):
        for _ in range(2):
            tests.append(fmt(vals(n), rng.randint(1, n)))
    tests.append(fmt(vals(16), 8))
    tests.append(fmt(vals(16), 7))
    tests.append(fmt(vals(16), 9))
    tests.append(fmt(vals(16), 6))
    tests.append(fmt(vals(16), 1))
    return tests

